L10_1 = "<color=#ff3636>두려워하지 마라. 움직이지 말고 오늘 ■■께서 너희를 어떻게 구원하시는가 보아라.</color>"
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "m_bTalkCenterFadeIn"
L9_1[L10_1] = true
L10_1 = "<color=#ff3636>恐れるな。その場を動かず、今日■■様が汝らをどのように救われるのかを見よ。</color>"
L9_1.m_Talk_JPN = L10_1
L10_1 = "<color=#ff3636>Fear not. Stand still and witness how ■■ shall deliver you today.</color>"
L9_1.m_Talk_ENG = L10_1
