L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "<color=#ff3636>■■께서 너희를 위하여 싸워주실 터이니 모두들 진정하여라.</color>"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "m_bTalkCenterFadeIn"
L10_1[L11_1] = true
