L47_1 = "USER_ADMIN_NULL_NULL"
L46_1.m_CharStrID = L47_1
L47_1 = "자네가 20년 전과 비교해서 변한 게 없다는 건 아직 그 마음가짐을 갖고 있다는 뜻일세."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "君が20年前と変わっていないということは、まだその気持ちを忘れていないということだ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "If you haven't changed in twenty years, that means you still carry that resolve."
L46_1.m_Talk_ENG = L47_1
L47_1 = "你說你20年來沒有改變，那就代表你心裡依然抱著同樣的信念。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "If you haven't changed in twenty years, that means you still carry that resolve."
L46_1.m_Talk_DEU = L47_1
