L49_1 = "USER_ADMIN_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "희생에 아파하고, 자신의 역할에 고뇌하고, 더 나은 방법을 찾느라 고통받고 있지."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "犠牲に悲しみ、己の役割に悩み、よりよい方法を探すために苦しんでいる。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "You grieve for sacrifice, struggle with your duty, and torment yourself searching for better paths."
L48_1.m_Talk_ENG = L49_1
L49_1 = "你會為犧牲痛苦、會為自己的責任掙扎，也會為尋找更好的做法而煩惱。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "You grieve for sacrifice, struggle with your duty, and torment yourself searching for better paths."
L48_1.m_Talk_DEU = L49_1
L49_1 = "You grieve for sacrifice, struggle with your duty, and torment yourself searching for better paths."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
