L50_1 = "최고 관리자님의 의견을 빌리자면… <color=#ffd34c>우리 힘으로는 죽었다 깨어나도 놈을 죽일 수 없다.</color>라고 하시더군."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "最高管理者の言葉を借りると……<color=#ffd34c>我々の力では死んでもやつを殺せない</color>そうだ。"
