L4_1 = "크라켄은 몸이 반 토막이 나도 재생하는, 사실상 우리가 죽일 수 없는 수준의 괴물이었다."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "クラーケンは身体が真っ二つになっても再生する、事実上、私たちの手では殺せない化け物だった。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "Kraken regenerated even after being split in half. It was practically immortal to us."
L3_1.m_Talk_ENG = L4_1
L4_1 = "克拉肯就算被切成兩半也會再生，是我們根本殺不死的怪物。"
